# Las expresiones se escriben una sola vez; para la versión inglesa se traducen las pocas palabras que contienen.
EXPR_EN = [('miles de millones USD', 'USD billions'), ('costo corriente', 'current cost'), ('costo histórico', 'historical cost'),
           ('% del PIB', '% of GDP'), ('% del ingreso', '% of income'), ('% del excedente', '% of surplus'), ('% de la ganancia', '% of profit'),
           ('% del valor agregado', '% of value added'), ('% de K', '% of K'), ('USD 2017 / h', '2017 USD / h'), ('ρ de Spearman', 'Spearman ρ'),
           ('parte salarial', 'labour share'), ('h recibidas', 'h received'), ('h entregadas', 'h delivered'), ('h prod.', 'prod. h'),
           ('h nec.', 'nec. h'), ('h plus.', 'surpl. h'), ('h púb.', 'pub. h'), ('población', 'population'), ('millones', 'millions'),
           ('(índice)', '(index)'), ('índice', 'index'), ('hist.', 'hc'), ('oper.', 'op.'), ('activos', 'assets'), ('sin CHN', 'excl. CHN'),
           ('neta', 'net'), ('neto', 'net'), ('VAN', 'NVA'), ('EBE', 'NOS'), ('100 = promedio', '100 = average'), ('quiebre', 'break')]


def expresion_en(x):
    for a, b in EXPR_EN:
        x = x.replace(a, b)
    return x


def entrada(codigo):
    """(nombre ES, nombre EN, expresión, qué ES, qué EN) para un código de serie; None si no está en el glosario."""
    if codigo in G:
        return G[codigo]
    if codigo.endswith('_i') and codigo[:-2] in G:
        b = G[codigo[:-2]]
        return (b[0] + ' (índice)', b[1] + ' (index)', b[2] + ' · 1982 = 100',
                b[3] + ' Aquí, como índice: 1982 = 100.', b[4] + ' Here as an index: 1982 = 100.')
    if codigo in EMPRESAS:
        return (codigo, codigo, 'Π oper. / K', f'Tasa de ganancia de {codigo}: ganancia operativa sobre su capital fijo (%).',
                f'Rate of profit of {codigo}: operating profit over its fixed capital (%).')
    if codigo.startswith('desv_') and codigo[5:] in PAISES:
        es, en = PAISES[codigo[5:]]
        return (f'Desviación precio/valor: {es}', f'Price/value deviation: {en}', '|p − w| / w',
                f'Desviación media de los precios de las ramas de {es} respecto de sus valores en horas.',
                f'Mean deviation of the prices of industries in {en} from their values in hours.')
    if codigo in PAISES:
        es, en = PAISES[codigo]
        return (f'Horas recibidas en el comercio: {es}', f'Hours received in trade: {en}', 'mmh',
                f'Horas de trabajo netas recibidas (+) o entregadas (−) por {es} en el comercio (miles de millones).',
                f'Net labour hours received (+) or delivered (−) by {en} in trade (billions).')
    return None
